 async function captureColors(doc){
  const canvas=doc.createElement('canvas');canvas.width=canvas.height=1;const ctx=canvas.getContext('2d'),cache=new Map();
  function convert(value){return value.replace(/(?:color|color-mix|oklch|oklab|lch|lab)\([^()]*\)/gi,color=>{if(cache.has(color))return cache.get(color);ctx.clearRect(0,0,1,1);ctx.fillStyle=color;ctx.fillRect(0,0,1,1);const p=ctx.getImageData(0,0,1,1).data,rgb='rgba('+p[0]+','+p[1]+','+p[2]+','+(p[3]/255)+')';cache.set(color,rgb);return rgb})}
  for(const el of doc.querySelectorAll('*')){const style=doc.defaultView.getComputedStyle(el);for(const prop of ['color','background-color','border-top-color','border-right-color','border-bottom-color','border-left-color','outline-color','text-decoration-color','box-shadow','text-shadow','background-image','fill','stroke']){const value=style.getPropertyValue(prop);if(/(?:color|color-mix|oklch|oklab|lch|lab)\(/i.test(value))el.style.setProperty(prop,convert(value),'important')}}
  // Rasterize SVG data images for the canvas exporter, which otherwise skips
  // URI-encoded SVG stick pictures in saved work. Keep their displayed size.
  await Promise.all([...doc.images].filter(img=>img.src.startsWith('data:image/svg+xml')).map(async img=>{await img.decode().catch(()=>{});if(!img.naturalWidth)return;const raster=doc.createElement('canvas');raster.width=img.naturalWidth*2;raster.height=img.naturalHeight*2;raster.getContext('2d').drawImage(img,0,0,raster.width,raster.height);img.src=raster.toDataURL('image/png');await img.decode()}));
 }

