 function speakPage(){
  if(speech){stop();return}
  if(!window.speechSynthesis||!window.SpeechSynthesisUtterance){toast('Voice instructions are unavailable in this browser.');return}
  if(!audio){audio=true;write('audio',true);audioUI()}
  stop();const text=current?(grade===2?'Rocky is your Excite guide. ':'Luna is your Inspire guide. ')+current.title+'. '+current.prompt+' '+current.directions:document.body.dataset.view==='homework'?(assignmentKind==='classwork'?'Classwork':'Homework')+' for October nineteenth through twenty third. '+(grade===2?'Excite with Rocky. ':'Inspire with Luna. ')+(homeworkDay===null?(assignmentKind==='classwork'?'Choose a day, then one of four sets. Every set has twenty mixed question pages.':'Choose a day. Each day has twenty mixed math questions.'):assignmentDays()[homeworkDay].weekday+'. '+(assignmentKind==='classwork'&&classworkSet===null?'Choose one of four sets. Each set has twenty pages.':'Choose Start or Continue to work on one question at a time. Your work saves with your rover ID.')) :document.body.dataset.view==='library'?(grade===2?'Excite with Rocky. Grade two. ':'Inspire with Luna. Grade three. ')+'Choose a math topic, then choose an activity. Use the search box to find an activity. The Next and Previous buttons show more activities.':'Welcome to Math Landing with Rocky and Luna. Choose one of the twenty moon rover buttons as your student ID. Rocky leads Excite for grade two. Luna leads Inspire for grade three. Each question has models, an answer check, voice instructions and a Stop voice button. Your work saves in this browser.';
  speech=new SpeechSynthesisUtterance(text);speech.lang='en-CA';speech.rate=.88;speech.onend=stop;speech.onerror=stop;
  $('stopVoice').disabled=false;$('voiceInstructions').innerHTML='▶ <span>Reading…</span>';$('hear').innerHTML='■ <span>Stop reading</span>';window.speechSynthesis.speak(speech);
 }

 function showWeekCatalog(kind=assignmentKind){
  if(!studentChosen){chooseProfile();return}const isClass=kind==='classwork',name=isClass?'Classwork':'Homework',days=(isClass?window.ML_CLASSWORK:window.ML_HOMEWORK).grades[grade],total=isClass?400:100,perDay=isClass?80:20;
  modal(name+' PNG catalog · October 19–23','<p><strong>'+(grade===2?'Excite · Grade 2':'Inspire · Grade 3')+'</strong> · '+safe(supplies.find(s=>s[0]===student)[1])+'</p><p>Save the question pages for the week as pictures in Excel or a PDF. Excel opens on PNG pages: portrait, 10 pictures per printed page. Saved models and answers remain in the detailed worksheet. Each PDF page has one question.</p><label class="week-catalog-scope">Choose pages <select id="weekCatalogDays"><option value="all">Whole week · '+total+' pages</option>'+days.map((d,i)=>'<option value="'+i+'">'+safe(d.label)+' · '+perDay+' pages</option>').join('')+'</select></label><p class="help-note">'+(isClass?'Four sets of 20 pages each day.':'20 mixed questions each day.')+' Only the selected grade and work type are included.</p><div class="calendar-audio"><button id="weekCatalogHear">▶ Hear instructions</button><button id="weekCatalogStop">■ Stop voice</button></div>','<button id="weekCatalogExcel" class="primary">↓ Excel with PNGs</button><button id="weekCatalogPDF" class="primary">↓ PDF with PNGs</button>');
  const start=format=>{const selected=$('weekCatalogDays').value;return myWorkExcel({weekKind:kind,format,day:selected==='all'?null:+selected})};$('weekCatalogExcel').onclick=()=>start('xlsx');$('weekCatalogPDF').onclick=()=>start('pdf');$('weekCatalogStop').onclick=stop;$('weekCatalogHear').onclick=()=>{stop();if(!audio||!window.speechSynthesis)return;speech=new SpeechSynthesisUtterance('Save the '+name.toLowerCase()+' question pictures for October nineteenth through twenty third. Choose the whole week, or just one day. Choose Excel with PNGs for an Excel workbook, or PDF with PNGs for a PDF with one question on each page. Only '+(grade===2?'Excite grade two':'Inspire grade three')+' is included.');speech.lang='en-CA';speech.rate=.87;speechSynthesis.speak(speech)};
 }
 $('weekCatalogButton').onclick=()=>showWeekCatalog();
 function showWeekCalendar(kind='homework'){saveCurrent();const days=(kind==='classwork'?window.ML_CLASSWORK:window.ML_HOMEWORK).grades[grade].map(d=>({...d,questions:d.sets?d.sets.flatMap(s=>s.questions):d.questions}));return window.ML_SHOW_WEEK_CALENDAR({kind,grade,rover:supplies.find(s=>s[0]===student)?.[1]||'Choose a rover ID',days,catalog:C,done:q=>!!records[recordKey(q)]?.done,modal,download,stop,audio,switchKind:showWeekCalendar,openCatalog:()=>showWeekCatalog(kind)})}
 document.addEventListener('click',e=>{const button=e.target?.closest?.('[data-week-calendar]');if(button)showWeekCalendar(button.dataset.weekCalendar||(['homework','learn'].includes(document.body.dataset.view)&&assignmentKind==='classwork'?'classwork':'homework'))});
 function assignmentDays(){return (assignmentKind==='classwork'?window.ML_CLASSWORK:window.ML_HOMEWORK).grades[grade]}
 function assignmentQuestions(){const day=assignmentDays()[homeworkDay];return assignmentKind==='classwork'?day.sets[classworkSet].questions:day.questions}
 function assignmentReturn(){return assignmentKind==='classwork'?classwork(homeworkDay,classworkSet):homework(homeworkDay)}
 function classwork(day=null,set=null){return homework(day,set,'classwork')}
 function homework(day=null,set=null,kind='homework'){
  assignmentKind=kind;classworkSet=set;
  if(!studentChosen){pendingHomework={day,set,kind};chooseProfile();return}
  saveCurrent();show('homework');homeworkDay=day;
  const isClass=kind==='classwork',name=isClass?'Classwork':'Homework',days=assignmentDays(),selected=day===null?null:days[day],isQuestionList=selected&&(!isClass||set!==null),level=grade===2?'Excite with Rocky':'Inspire with Luna';
  $('homeworkCalendar').hidden=false;$('homeworkCalendar').dataset.weekCalendar=kind;$('homeworkTitle').textContent=selected?selected.label+(isClass&&set!==null?' · Set '+(set+1):''):name+' · October 19–23';
  $('homeworkLevel').textContent=level+' · '+(isClass?'4 sets × 20 pages each day':'20 questions each day');
  $('homeworkWeek').hidden=!!isQuestionList;$('homeworkQuestions').hidden=!isQuestionList;$('homeworkBack').hidden=day===null;$('homeworkStart').hidden=!isQuestionList;
  $('homeworkBack').textContent=isClass&&set!==null?'← '+selected.weekday+' sets':'← '+name+' week';
  $('homeworkWeek').classList.toggle('classwork-sets',!!(isClass&&selected));$('homeworkWeek').setAttribute('aria-label',isClass&&selected?'Four classwork sets':'Five '+name.toLowerCase()+' days');
  $('homeworkNote').textContent=isQuestionList?'Work through one question at a time. Your models, answers and Finished ticks save with your rover ID.':isClass?'Choose a day, then a set. Each set has 20 mixed question pages from the project.':'A mixed selection from every activity section across the week. Each day has 20 different questions and its own progress.';
  if(!isQuestionList){
   const cards=isClass&&selected?selected.sets:days;
   $('homeworkWeek').innerHTML=cards.map((d,index)=>{const entries=isClass?(selected?d.questions:d.sets.flatMap(s=>s.questions)):d.questions,done=entries.filter(x=>record(C.find(q=>q.id===x.id)).done).length,title=isClass&&selected?d.label:d.weekday,subtitle=isClass&&selected?'20 question pages':'October '+(19+index)+', 2026';return '<article class="homework-day"><button class="homework-picture" data-assignment-picture="'+index+'" aria-label="Open '+safe(title)+' picture"><img src="'+d.picture.src+'" alt="'+safe(d.picture.alt)+'" draggable="false"><span aria-hidden="true">⤢</span></button><button data-assignment-card="'+index+'"><strong>'+safe(title)+'</strong><span>'+subtitle+'</span><small>'+done+' of '+entries.length+' finished</small><b>'+(isClass&&!selected?'Choose one of 4 sets ↗':'Open '+name.toLowerCase()+' ↗')+'</b></button></article>'}).join('');
  }else{
   $('homeworkQuestions').innerHTML=assignmentQuestions().map((entry,index)=>{const q=C.find(q=>q.id===entry.id),done=record(q).done;return '<button data-assignment-question="'+index+'" class="'+(done?'is-done':'')+'"><span class="homework-question-number">'+(index+1)+(done?' ✓':'')+'</span><strong>'+safe(q.title)+'</strong><small>'+safe(q.codes.join(' · '))+'</small></button>'}).join('');
   $('homeworkStart').textContent=assignmentQuestions().every(x=>record(C.find(q=>q.id===x.id)).done)?'Review set →':'Start / continue →';
  }
 }
 function openHomeworkQuestion(index){openQuestion(C.find(q=>q.id===assignmentQuestions()[index].id))}
 function assignmentSelector(){
  if(assignmentKind==='classwork')return assignmentDays().flatMap((d,day)=>d.sets.map((s,set)=>'<option value="'+(day*4+set)+'">Classwork · '+d.label+' · Set '+(set+1)+' · 20 pages</option>')).join('');
  return assignmentDays().map((d,i)=>'<option value="'+i+'">Homework · '+d.label+' · 20 questions</option>').join('');
 }
