  if(view==='homework'){const day=homeworkDay===null?null:assignmentDays()[homeworkDay],name=assignmentKind==='classwork'?'Classwork':'Homework',id='ui:'+assignmentKind+':'+grade+':'+(homeworkDay===null?'week':homeworkDay)+':'+(classworkSet===null?'sets':classworkSet);return {id,pageId:id,type:'menu',title:level+' · '+name+' · '+(day?day.label:'October 19–23')+(classworkSet===null?'':' · Set '+(classworkSet+1)),grade,codes:[],where:level+' · '+name,contextLabel:day?'October 19–23, 2026':'Week menu',route}}
  return {id:'ui:welcome',pageId:'welcome',type:'entry',title:'Math Landing · Title and rover entry',grade:0,codes:[],where:'Title page · Both paths',contextLabel:'Rover IDs and grade entry',route:{...route,view:'home'}};
