 function navigateAuditPage(note){const r=note.route||{};saveCurrent();if(r.student&&supplies.some(s=>s[0]===r.student)&&student!==r.student)chooseSpaceId(r.student);if([2,3].includes(r.grade)){grade=r.grade;$('grade').value=grade;write('grade',grade);refreshGroups()}if(r.question){homeworkDay=r.day??null;classworkSet=r.set??null;assignmentKind=r.kind||'homework';const q=C.find(q=>q.id===r.question);if(q)openQuestion(q);return}if(r.view==='homework'){homework(r.day??null,r.set??null,r.kind||'homework');return}if(r.view==='library'){library();topic=r.topic||'all';page=r.page||0;$('search').value=r.search||'';drawLibrary();return}home()}

